export function t(key:string):string { return en[key] ?? key; }
/** `Alt+L` → `⌥L` on macOS, `Alt+L` elsewhere. */
export const shortcutLabel=(shortcut:string)=>typeof navigator!=='undefined'&&/Mac/.test(navigator.platform)?shortcut.replace(/Alt\+/g,'⌥').replace(/Shift\+/g,'⇧'):shortcut;
